from langchain_core.prompts import ChatPromptTemplate
from langchain_core.documents import Document
from langchain_core.messages import HumanMessage
from langchain_openai import ChatOpenAI, OpenAIEmbeddings
from langgraph.graph import START, StateGraph
from typing_extensions import List, TypedDict
from dotenv import load_dotenv
from langchain_chroma import Chroma
import base64
import requests


# Define state for application
class State(TypedDict):
    question: dict
    context: List[Document]
    answer: str


class CustomGraph:
    def __init__(self, prompt, llm, vector_store):
        self.prompt = prompt
        self.llm = llm
        self.vector_store = vector_store

    def retrieve(self, state: State):
        print(f"SEARCHING DOCUMENTS...\n{'='*20}")
        # Extract text from question for vector search
        question_text = state["question"]["text"] if isinstance(state["question"], dict) else state["question"]
        retrieved_docs = self.vector_store.similarity_search(question_text)
        print(f"searched...{retrieved_docs[0].page_content[:100]}\n...\n{'='*20}")
        return {"context": retrieved_docs}

    def generate(self, state: State):
        print(f"GENERATING ANSWER...\n{'='*20}")
        docs_content = "\n\n".join(doc.page_content for doc in state["context"])
        
        # Check if question has text only or text + image
        if isinstance(state["question"], dict) and "image" in state["question"]:
            # Multimodal question (text + image)
            message_content = [
                {"type": "text", "text": f"""
    You are an assistant for question-answering tasks.
    You are also an assistant specialized in robotics, machinery, and mechanical engineering.
    Use the following pieces of retrieved context to answer the question. 
    If you don't know the answer, just say that you don't know. 
    Context: {docs_content} 
    Answer:
    """}
            ]
            
            # Add question text
            if "text" in state["question"]:
                message_content.append({
                    "type": "text", 
                    "text": f"Question: {state['question']['text']}"
                })
            
            # Add image (base64)
            if state["question"]["image"]:
                message_content.append({
                    "type": "image_url",
                    "image_url": {"url": f"data:image/jpeg;base64,{state['question']['image']}"},
                })
            
            message = HumanMessage(content=message_content)
        else:
            # Text-only question
            question_text = state["question"]["text"] if isinstance(state["question"], dict) else state["question"]
            message = HumanMessage(
                content=[
                    {"type": "text", "text": f"""
    You are an assistant for question-answering tasks.
    You are also an assistant specialized in robotics, machinery, and mechanical engineering.
    Use the following pieces of retrieved context to answer the question. 
    If you don't know the answer, just say that you don't know. 
    Question: {question_text} 
    Context: {docs_content} 
    Answer:
    """}
                ]
            )
        
        response = self.llm.invoke([message])
        return {"answer": response.content}

    def build_graph(self):
        graph_builder = StateGraph(State).add_sequence([self.retrieve, self.generate])
        graph_builder.add_edge(START, "retrieve")
        return graph_builder.compile()


def download_and_encode_image(image_url: str) -> str:
    """Download image from URL and encode to base64"""
    try:
        response = requests.get(image_url)
        response.raise_for_status()
        return base64.b64encode(response.content).decode('utf-8')
    except Exception as e:
        print(f"Error downloading image: {e}")
        return None


def main(is_only_text_mode: bool=True, question: dict=None):

    load_dotenv(override=True)

    llm = ChatOpenAI(model="gpt-4o-mini")
    # Define prompt for question-answering
    prompt = ChatPromptTemplate([
        ("human", """
    You are an assistant for question-answering tasks.
    You are also an assistant specialized in robotics, machinery, and mechanical engineering.
    Use the following pieces of retrieved context to answer the question. 
    If you don't know the answer, just say that you don't know. 
    Question: {question} 
    Context: {context} 
    Answer:
    """)])

    embeddings = OpenAIEmbeddings(model="text-embedding-3-small")
    vector_store = Chroma(
        persist_directory="./chroma_db",
        embedding_function=embeddings
    )

    graph = CustomGraph(prompt, llm, vector_store).build_graph()

    response = graph.invoke({"question": question})

    return response["answer"]


